TASK AND SPECIFICATIONS
{
  "schema_version": 1,
  "id": "SELF008",
  "kind": "self_built",
  "title": "Consecutive scan qualification with an immediate trip",
  "difficulty": "easy",
  "provenance": {
    "source_type": "independent_synthesis",
    "source_file": "scripts/build_self_dataset.py",
    "source_index": 8,
    "adaptation": "Independently specified for this project; no public task was copied. The coding assistant chose the state variables, priority order and fixed scan traces, then reviewed the traces against a separate Python transition implementation.",
    "rationale": "A cyclic quality check accepts a request only after a configurable number of consecutive healthy invocations.",
    "review": "Assistant consistency review of initialization, simultaneous commands, retained state and recovery boundaries; independent Python oracle checked against manual expected traces. Not an industrial safety certification or external expert review."
  },
  "requirements": "Preset is valid from 1 through 5. Initialize Count=0. If Trip TRUE, Request FALSE, or Preset invalid, clear Count and Ready. Otherwise Count becomes min(previous Count+1, Preset); Ready is TRUE exactly when Count reaches Preset. Count saturates. Changes of Preset take effect immediately using the same rule, so reducing Preset can qualify on that scan. This counts invocations, not elapsed milliseconds.",
  "scenario": "A cyclic quality check accepts a request only after a configurable number of consecutive healthy invocations.",
  "interface": [
    {
      "direction": "INPUT",
      "name": "Request",
      "type": "BOOL",
      "description": "Raw qualification request"
    },
    {
      "direction": "INPUT",
      "name": "Trip",
      "type": "BOOL",
      "description": "Immediate inhibit"
    },
    {
      "direction": "INPUT",
      "name": "Preset",
      "type": "USINT",
      "description": "Required consecutive scans, valid 1 through 5"
    },
    {
      "direction": "OUTPUT",
      "name": "Ready",
      "type": "BOOL",
      "description": "Qualified request"
    },
    {
      "direction": "OUTPUT",
      "name": "Count",
      "type": "USINT",
      "description": "Saturated consecutive scan count"
    }
  ],
  "initial_conditions": {
    "Count": 0,
    "Ready": false
  },
  "scan_semantics": "At scan k, sample every input once, read retained pre-state q[k], execute one transition, and observe outputs O[k] at the end of that same scan. Updated state becomes q[k+1]. Reset the instance before each test. Step 0 executes normally; initial conditions describe pre-state, not an extra delayed scan. All timing in this task is explicitly counted in invocations, not wall time.",
  "safety_priority": [
    "Trip, missing request and invalid Preset clear progress"
  ],
  "assumptions": [],
  "atomic_propositions": {
    "Request": "Raw qualification request Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Trip": "Immediate inhibit Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Preset": "Required consecutive scans, valid 1 through 5 Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Ready": "Qualified request Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Count": "Saturated consecutive scan count Boolean names are propositions; numeric names appear only inside defined predicates.",
    "first": "True only on the first invocation after resetting the FB instance.",
    "invalid": "Preset < 1 or Preset > 5.",
    "qualified": "Count >= Preset and Preset is valid.",
    "qCount": "Pre-scan Count, initially zero.",
    "nextCount": "min(qCount+1, Preset) as an integer expression."
  },
  "ltl": [
    {
      "id": "P1",
      "formula": "G((Trip | !Request | invalid) -> (!Ready & (Count = 0)))",
      "explanation": "Every interruption clears qualification immediately."
    },
    {
      "id": "P2",
      "formula": "G((Request & !Trip & !invalid) -> (Count = nextCount))",
      "explanation": "Healthy scans increment and saturate precisely."
    },
    {
      "id": "P3",
      "formula": "G(Ready <-> qualified)",
      "explanation": "The indication agrees with the post-scan count."
    },
    {
      "id": "P4",
      "formula": "G(!invalid -> ((Count >= 0) & (Count <= Preset)))",
      "explanation": "The counter stays within bounds."
    },
    {
      "id": "P5",
      "formula": "(G(Request & !Trip & !invalid)) -> F Ready",
      "explanation": "A perpetually valid request qualifies within at most five scans, even if valid Preset varies."
    }
  ],
  "tests": [
    {
      "id": "delay",
      "purpose": "Three scans qualify, hold saturates, trip clears",
      "steps": [
        {
          "inputs": {
            "Request": true,
            "Trip": false,
            "Preset": 3
          },
          "expected": {
            "Count": 1,
            "Ready": false
          }
        },
        {
          "inputs": {
            "Request": true,
            "Trip": false,
            "Preset": 3
          },
          "expected": {
            "Count": 2,
            "Ready": false
          }
        },
        {
          "inputs": {
            "Request": true,
            "Trip": false,
            "Preset": 3
          },
          "expected": {
            "Count": 3,
            "Ready": true
          }
        },
        {
          "inputs": {
            "Request": true,
            "Trip": false,
            "Preset": 3
          },
          "expected": {
            "Count": 3,
            "Ready": true
          }
        },
        {
          "inputs": {
            "Request": true,
            "Trip": true,
            "Preset": 3
          },
          "expected": {
            "Count": 0,
            "Ready": false
          }
        },
        {
          "inputs": {
            "Request": true,
            "Trip": false,
            "Preset": 3
          },
          "expected": {
            "Count": 1,
            "Ready": false
          }
        }
      ]
    },
    {
      "id": "bounds",
      "purpose": "Invalid presets and immediate reduced threshold",
      "steps": [
        {
          "inputs": {
            "Request": true,
            "Trip": false,
            "Preset": 0
          },
          "expected": {
            "Count": 0,
            "Ready": false
          }
        },
        {
          "inputs": {
            "Request": true,
            "Trip": false,
            "Preset": 6
          },
          "expected": {
            "Count": 0,
            "Ready": false
          }
        },
        {
          "inputs": {
            "Request": true,
            "Trip": false,
            "Preset": 5
          },
          "expected": {
            "Count": 1,
            "Ready": false
          }
        },
        {
          "inputs": {
            "Request": true,
            "Trip": false,
            "Preset": 1
          },
          "expected": {
            "Count": 1,
            "Ready": true
          }
        },
        {
          "inputs": {
            "Request": false,
            "Trip": false,
            "Preset": 5
          },
          "expected": {
            "Count": 0,
            "Ready": false
          }
        }
      ]
    }
  ]
}
